      command: ({ env }) => env.ULTRA_ZCODE_ACP_COMMAND || 'zcode-acp',
      argv: ({ cliCommand }) => ['--zcode-path', cliCommand, '--no-browser'],
      // The exact installed identity an enforcement qualification can bind
